# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
from datetime import date, timedelta

import pytest

from apps.accounts.tests.factories import StudentFactory
from apps.placements import selectors
from apps.placements.services import PlacementService
from apps.placements.tests.factories import (
    ApprovedPlacementFactory,
    OrganizationFactory,
    PlacementFactory,
)

pytestmark = pytest.mark.django_db


def test_each_role_sees_only_its_own_placements(coordinator):
    mine = ApprovedPlacementFactory()
    other = ApprovedPlacementFactory()
    assert set(selectors.placements_visible_to(mine.student)) == {mine}
    assert set(selectors.placements_visible_to(mine.workplace_supervisor)) == {mine}
    assert set(selectors.placements_visible_to(mine.academic_supervisor)) == {mine}
    assert set(selectors.placements_visible_to(coordinator)) == {mine, other}


def test_unknown_roles_see_nothing():
    ApprovedPlacementFactory()

    class Nobody:
        role = "GHOST"

    assert not selectors.placements_visible_to(Nobody()).exists()


def test_participants_and_get_placement():
    placement = ApprovedPlacementFactory()
    participants = selectors.placement_participants(placement.id)
    assert participants.student == placement.student
    assert participants.workplace_supervisor == placement.workplace_supervisor
    assert selectors.get_placement(placement.id) == placement
    assert selectors.placement_participants("00000000-0000-0000-0000-000000000000") is None


def test_open_placements_and_can_log_on():
    placement = ApprovedPlacementFactory()
    draft = PlacementFactory()
    today = date.today()
    assert placement in selectors.open_placements_on(today)
    assert draft not in selectors.open_placements_on(today)
    assert selectors.can_log_on(placement.id, today)
    assert not selectors.can_log_on(placement.id, today + timedelta(days=500))
    assert not selectors.can_log_on(draft.id, today)


def test_students_see_verified_organizations_and_their_own():
    student = StudentFactory()
    verified = OrganizationFactory(is_verified=True)
    own = OrganizationFactory(is_verified=False, created_by=student)
    hidden = OrganizationFactory(is_verified=False, created_by=StudentFactory())
    visible = set(selectors.organizations_visible_to(student))
    assert verified in visible
    assert own in visible
    assert hidden not in visible


def test_timeline_records_each_status_change_with_who_did_it(coordinator, academic_supervisor):
    placement = PlacementFactory()
    PlacementService.submit(actor=placement.student, placement=placement)
    PlacementService.return_for_changes(actor=coordinator, placement=placement, remarks="Fix it")
    timeline = selectors.placement_timeline(placement)
    assert [event["status"] for event in timeline] == ["DRAFT", "SUBMITTED", "RETURNED"]
    assert timeline[-1]["by"] == coordinator.full_name
    assert timeline[-1]["remarks"] == "Fix it"
